<template><div class="app-container"><el-button type="success" plain class="mb8" @click="exportData" v-hasPermi="['supply:ledger:export']">导出 Excel</el-button><el-form :inline="true" :model="query"><el-form-item label="订单号"><el-input v-model="query.number" clearable/></el-form-item><el-form-item label="供应商"><el-input v-model="query.supplierName" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="query.approvalStatus" clearable><el-option label="草稿" value="DRAFT"/><el-option label="审批中" value="IN_REVIEW"/><el-option label="已通过" value="APPROVED"/><el-option label="已作废" value="VOID"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><el-table v-loading="loading" :data="list"><el-table-column prop="orderNumber" label="订单号" min-width="180"/><el-table-column prop="supplierName" label="供应商" min-width="180"/><el-table-column prop="approvalStatus" label="订单状态" width="110"/><el-table-column label="订单金额" width="130"><template #default="s">¥{{money(s.row.totalCents)}}</template></el-table-column><el-table-column prop="receivedQuantity" label="已入库数量" width="120"/><el-table-column label="已通过发票" width="130"><template #default="s">¥{{money(s.row.approvedInvoiceCents)}}</template></el-table-column><el-table-column label="待审发票" width="130"><template #default="s">¥{{money(s.row.pendingInvoiceCents)}}</template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/></div></template>
<script setup lang="ts" name="SupplyLedger">
import { listCombinedLedger, exportCombinedLedger } from '@/api/supply'; import { saveAs } from 'file-saver'
const { proxy }=getCurrentInstance()!; const list=ref<any[]>([]); const loading=ref(false); const total=ref(0); const query=reactive({pageNum:1,pageSize:20,number:undefined as string|undefined,supplierName:undefined as string|undefined,approvalStatus:undefined as string|undefined}); async function load(){loading.value=true;try{const r=await listCombinedLedger(query);list.value=r.rows;total.value=r.total}finally{loading.value=false}};async function exportData(){const {pageNum,pageSize,...params}=query;const blob=await exportCombinedLedger(params);saveAs(blob as Blob,`供应链综合台账_${new Date().toISOString().slice(0,10)}.xlsx`);proxy.$modal.msgSuccess('导出成功')};function reset(){query.pageNum=1;query.number=undefined;query.supplierName=undefined;query.approvalStatus=undefined;load()};function money(v?:number){return ((v||0)/100).toFixed(2)};load()
</script>
